$(function(){window.addEventListener("scroll",function(){}),document.querySelectorAll(".js-fadeIns01").forEach(function(o){gsap.fromTo(o,{y:20,opacity:0},{y:0,duration:.8,opacity:1,scrollTrigger:{trigger:o,start:"top center"}})}),document.querySelectorAll(".js-fadeIns02").forEach(function(o){gsap.fromTo(o,{opacity:0},{duration:.8,opacity:1,scrollTrigger:{trigger:o,start:"top bottom"}})}),document.querySelectorAll(".js-parallax01").forEach(function(o){window.matchMedia("(max-width: 767px)").matches,gsap.fromTo(o.querySelector("img"),{yPercent:0},{yPercent:-15,ease:"none",scrollTrigger:{trigger:o,start:"top bottom",end:"bottom top",scrub:.3}})}),ScrollTrigger.config({autoRefreshEvents:"visibilitychange,DOMContentLoaded,load"})});